const data = $input.first().json;
const fecha = new Date();
fecha.setDate(fecha.getDate() - 1);
const fechaStr = fecha.toISOString().split('T')[0];

const texto = `REPORTE DIARIO DE TRIAJES - ${fechaStr}
================================

Resumen:
- Críticos: ${data.criticos || 0}
- Altos: ${data.altos || 0}
- Moderados: ${data.moderados || 0}
- Bajos: ${data.bajos || 0}

Total de triajes: ${data.total_triajes || 0}`;

return [{ json: { texto: texto, fecha: fechaStr } }];
